// BootstrapSaasRuntimeApplicationTemplate returns an isolated test project and
// the name of a composite ADC ApplicationTemplate in it, creating them if they
// don't exist.
//
// The project is created with resourcemanager.BootstrapProject, has the APIs in
// bootstrapAdcProjectServices enabled, and grants the SaaS Runtime service agent
// roles/saasservicemgmt.serviceAgent. It is isolated because ADC only creates
// Spaces in an App Hub management project, which requires setting the project's
// App Hub boundary to the project itself. The boundary is a project-wide
// setting that other tests (TestAccApphubBoundary_*) change in the default test
// project. Resources created in the project should be created there explicitly
// (for example, with `project = ...` in the config).
//
// The template has one component, "sa-comp-1", built from a standard template
// that wraps the Google-provided Service Account shared template, and two
// revisions:
//   - r-1: sa-comp-1 with parameter sa-1_project_id.
//   - r-2: same component and shared-template revision, plus parameter sa-1_name.
//
// Importing r-2 after r-1 re-runs the import without creating a new UnitKind or
// Release.
func BootstrapSaasRuntimeApplicationTemplate(t *testing.T) (project, template string) {
	config := transport_tpg.BootstrapConfig(t)
	if config == nil {
		return "", ""
	}
	p := resourcemanager.BootstrapProject(t, bootstrapAdcProjectPrefix, envvar.GetTestBillingAccountFromEnv(t), bootstrapAdcProjectServices)
	if p == nil {
		t.Fatal("Bootstrapping failed. Could not bootstrap the isolated test project.")
	}
	project = p.ProjectId
	number := strconv.FormatInt(p.ProjectNumber, 10)
	b := &adcBootstrapper{t: t, config: config, project: project, number: number}

	// The service agent is created on first use; create it now so that it can
	// be granted its role.
	b.waitAt("https://serviceusage.googleapis.com/v1beta1/", b.send("POST", fmt.Sprintf("https://serviceusage.googleapis.com/v1beta1/projects/%s/services/saasservicemgmt.googleapis.com:generateServiceIdentity", number), nil))
	resourcemanager.BootstrapProjectIamMembers(t, project, []resourcemanager.IamMember{
		{
			Member: "serviceAccount:service-{project_number}@gcp-sa-saasservicemgmt.iam.gserviceaccount.com",
			Role:   "roles/saasservicemgmt.serviceAgent",
		},
	})

	space := fmt.Sprintf("projects/%s/locations/%s/spaces/%s", project, bootstrapAdcLocation, bootstrapAdcSpace)
	composite := space + "/applicationTemplates/" + bootstrapAdcComposite

	// Fast path: the fixture is complete.
	if b.exists(composite+"/revisions/r-1") && b.exists(composite+"/revisions/r-2") {
		return project, composite
	}
	log.Printf("[DEBUG] Bootstrapping ADC composite template %s", composite)

	// Space.
	if !b.exists(space) {
		b.ensureAppHubBoundary()
		b.create(fmt.Sprintf("projects/%s/locations/%s/spaces?space_id=%s", project, bootstrapAdcLocation, bootstrapAdcSpace), map[string]interface{}{})
	}
	b.send("PATCH", space+"?updateMask=enable_gcp_shared_templates", map[string]interface{}{"enableGcpSharedTemplates": true})

	// Standard template wrapping the Google Service Account shared template.
	standard := space + "/applicationTemplates/" + bootstrapAdcStandard
	if !b.exists(standard + "/revisions/r-1") {
		b.create(space+"/applicationTemplates?application_template_id="+bootstrapAdcStandard, map[string]interface{}{
			"name":            standard,
			"compositionType": "STANDARD",
		})
		b.create(standard+"/components?component_id=sa-1", map[string]interface{}{
			"name":                      standard + "/components/sa-1",
			"sharedTemplateRevisionUri": bootstrapAdcSharedSATmplRev,
			"parameters":                []interface{}{map[string]interface{}{"key": "project_id", "value": project}},
		})
		b.send("PATCH", standard+"?updateMask=root_input_variables", map[string]interface{}{
			"name": standard,
			"rootInputVariables": []interface{}{
				map[string]interface{}{"variable": "project_id", "componentUri": standard + "/components/sa-1"},
				map[string]interface{}{"variable": "name", "componentUri": standard + "/components/sa-1"},
			},
		})
		b.commit(standard, "r-1")
	}

	// Catalog with the standard template, shared to the Space.
	catalog := space + "/catalogs/" + bootstrapAdcCatalog
	if !b.exists(catalog) {
		b.wait(b.create(space+"/catalogs?catalog_id="+bootstrapAdcCatalog, map[string]interface{}{}))
	}
	catalogTemplate := catalog + "/templates/" + bootstrapAdcStandard
	if !b.exists(catalogTemplate) {
		b.wait(b.create(catalog+"/templates?catalog_template_id="+bootstrapAdcStandard, map[string]interface{}{
			"name":             catalogTemplate,
			"templateCategory": "APPLICATION_TEMPLATE",
		}))
	}
	catalogRevision := catalogTemplate + "/revisions/r-1"
	if !b.exists(catalogRevision) {
		b.wait(b.create(catalogTemplate+"/revisions?catalog_template_revision_id=r-1", map[string]interface{}{
			"name":                              catalogRevision,
			"type":                              "APPLICATION",
			"applicationTemplateRevisionSource": standard + "/revisions/r-1",
		}))
	}
	// The service fills in the revision's input variables asynchronously. A
	// share created before that copies a revision without them, and adding the
	// component below then fails with "parameter ... is not declared".
	b.poll("catalog template revision input variables", func() (bool, error) {
		res, err := b.get(catalogRevision)
		if err != nil {
			return false, err
		}
		md, _ := res["templateMetadata"].(map[string]interface{})
		inputs, _ := md["terraformInput"].([]interface{})
		return len(inputs) > 0, nil
	})
	if !b.exists(catalog + "/shares/" + bootstrapAdcShare) {
		b.wait(b.create(catalog+"/shares?share_id="+bootstrapAdcShare, map[string]interface{}{
			"name":             catalog + "/shares/" + bootstrapAdcShare,
			"destinationSpace": space,
		}))
	}
	// The share creates a shared template with a generated ID.
	var sharedRevision string
	b.poll("shared template revision", func() (bool, error) {
		res, err := b.get(space + "/sharedTemplates")
		if err != nil {
			return false, err
		}
		list, _ := res["sharedTemplates"].([]interface{})
		for _, i := range list {
			st, _ := i.(map[string]interface{})
			if st["originTemplate"] == catalogTemplate {
				name, _ := st["name"].(string)
				if b.exists(name + "/revisions/r-1") {
					sharedRevision = name + "/revisions/r-1"
					return true, nil
				}
			}
		}
		return false, nil
	})

	// Composite template, revisions r-1 and r-2.
	component := composite + "/components/" + bootstrapAdcComponent
	if !b.exists(composite) {
		b.create(space+"/applicationTemplates?application_template_id="+bootstrapAdcComposite, map[string]interface{}{
			"name":            composite,
			"compositionType": "COMPOSITE",
		})
	}
	if !b.exists(composite + "/revisions/r-1") {
		if !b.exists(component) {
			b.create(composite+"/components?component_id="+bootstrapAdcComponent, map[string]interface{}{
				"name":                      component,
				"sharedTemplateRevisionUri": sharedRevision,
				"parameters":                []interface{}{map[string]interface{}{"key": "sa-1_project_id", "value": project}},
			})
		}
		b.commit(composite, "r-1")
	}
	if !b.exists(composite + "/revisions/r-2") {
		b.send("PATCH", component+"?updateMask=parameters", map[string]interface{}{
			"name": component,
			"parameters": []interface{}{
				map[string]interface{}{"key": "sa-1_project_id", "value": project},
				map[string]interface{}{"key": "sa-1_name", "value": "tf-bootstrap-sa-name"},
			},
		})
		b.commit(composite, "r-2")
	}
	return project, composite
}

type adcBootstrapper struct {
	t       *testing.T
	config  *transport_tpg.Config
	project string
	number  string
}

func (b *adcBootstrapper) url(path string) string {
	if strings.HasPrefix(path, "https://") {
		return path
	}
	return bootstrapAdcBaseUrl + path
}

func (b *adcBootstrapper) request(method, path string, body map[string]interface{}) (map[string]interface{}, error) {
	return transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    b.config,
		Method:    method,
		Project:   b.project,
		RawURL:    b.url(path),
		UserAgent: b.config.UserAgent,
		Body:      body,
	})
}

func (b *adcBootstrapper) get(path string) (map[string]interface{}, error) {
	return b.request("GET", path, nil)
}

// exists reports whether GET path succeeds; it fails the test on errors other than 404.
func (b *adcBootstrapper) exists(path string) bool {
	b.t.Helper()
	_, err := b.get(path)
	if err == nil {
		return true
	}
	if transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
		return false
	}
	b.t.Fatalf("Bootstrapping failed. Error getting %s: %s", path, err)
	return false
}

func (b *adcBootstrapper) send(method, path string, body map[string]interface{}) map[string]interface{} {
	b.t.Helper()
	res, err := b.request(method, path, body)
	if err != nil {
		b.t.Fatalf("Bootstrapping failed. Error calling %s %s: %s", method, path, err)
	}
	return res
}

// create POSTs path and treats 409 (already exists) as success, returning nil.
func (b *adcBootstrapper) create(path string, body map[string]interface{}) map[string]interface{} {
	b.t.Helper()
	res, err := b.request("POST", path, body)
	if err != nil {
		if transport_tpg.IsGoogleApiErrorWithCode(err, 409) {
			return nil
		}
		b.t.Fatalf("Bootstrapping failed. Error calling POST %s: %s", path, err)
	}
	return res
}

// commit commits the template draft and checks the new revision's ID.
func (b *adcBootstrapper) commit(template, wantRevision string) {
	b.t.Helper()
	res := b.send("POST", template+":commit", nil)
	if name, _ := res["name"].(string); name != template+"/revisions/"+wantRevision {
		b.t.Fatalf("Bootstrapping failed. Committing %s created revision %q, want %q", template, name, wantRevision)
	}
}

// wait waits for res to finish if it is an ADC long-running operation.
func (b *adcBootstrapper) wait(res map[string]interface{}) {
	b.t.Helper()
	b.waitAt(bootstrapAdcBaseUrl, res)
}

// waitAt waits for res to finish if it is a long-running operation of the API
// at baseUrl.
func (b *adcBootstrapper) waitAt(baseUrl string, res map[string]interface{}) {
	b.t.Helper()
	name, _ := res["name"].(string)
	if !strings.Contains(name, "/operations/") {
		return
	}
	b.poll("operation "+name, func() (bool, error) {
		op, err := b.get(baseUrl + name)
		if err != nil {
			return false, err
		}
		if done, _ := op["done"].(bool); !done {
			return false, nil
		}
		if e, ok := op["error"]; ok {
			return false, fmt.Errorf("operation %s failed: %v", name, e)
		}
		return true, nil
	})
}

// poll calls f every 5 seconds until it returns true, for up to 5 minutes.
func (b *adcBootstrapper) poll(what string, f func() (bool, error)) {
	b.t.Helper()
	deadline := time.Now().Add(5 * time.Minute)
	for {
		ok, err := f()
		if err != nil {
			b.t.Fatalf("Bootstrapping failed. Error waiting for %s: %s", what, err)
		}
		if ok {
			return
		}
		if time.Now().After(deadline) {
			b.t.Fatalf("Bootstrapping failed. Timed out waiting for %s", what)
		}
		time.Sleep(5 * time.Second)
	}
}

// ensureAppHubBoundary makes the project an App Hub management project by
// setting its boundary to itself, which ADC requires to create a Space.
func (b *adcBootstrapper) ensureAppHubBoundary() {
	b.t.Helper()
	boundary := fmt.Sprintf("https://apphub.googleapis.com/v1/projects/%s/locations/global/boundary", b.project)
	res := b.send("GET", boundary, nil)
	crmNode := "projects/" + b.number
	if res["crmNode"] == crmNode {
		return
	}
	log.Printf("[DEBUG] Setting App Hub boundary of %s to %s", b.project, crmNode)
	b.waitAt("https://apphub.googleapis.com/v1/", b.send("PATCH", boundary+"?updateMask=crmNode", map[string]interface{}{"crmNode": crmNode}))
}
